mapper.select:
SELECT T.AFFIRM_OBJECT, T.AFFIRM_TYPE_ID, T.AFFIRM_LEVEL, T.AFFIRMOR_ID, HR.EMPID, HR.LOCAL_NAME, GET_DEPT_NAME(HR.DEPTNO, #{lang, jdbcType=VARCHAR}) AS DEPT_NAME FROM SY_AFFIRM_RELATION_SPECIAL T LEFT JOIN HR_EMPLOYEE HR ON HR.PERSON_ID = T.AFFIRMOR_ID WHERE T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND T.AFFIRM_OBJECT = #{affirmObject, jdbcType=VARCHAR}
AND T.AFFIRM_TYPE_ID = #{affirmTypeNo, jdbcType=VARCHAR}
ORDER BY T.AFFIRM_OBJECT, T.AFFIRM_TYPE_ID, T.AFFIRM_LEVEL

mapper.delete:
DELETE FROM SY_AFFIRM_RELATION_SPECIAL T
 WHERE T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND T.AFFIRM_OBJECT = #{affirmObject, jdbcType=VARCHAR}
   AND T.AFFIRM_TYPE_ID = #{affirmTypeNo, jdbcType=VARCHAR}
